const loopItem = $('Loop Produtos').item.json;
const respostaApi = $input.item.json;

return { ...loopItem, ...respostaApi };

const todos = $input.all();
const staticData = $getWorkflowStaticData('global');
if (!staticData.ultimosPrecos) staticData.ultimosPrecos = {};

const saida = [];

for (const item of todos) {
    const html = item.json.data;
    const loja = item.json.loja;
    const precoAlvo = item.json.precoAlvo;
    const nomeMonitorado = item.json.nome;
    const filtro = item.json.filtro || [];
    const excluir = item.json.excluir || [];

    function filtraCandidatos(produtos) {
        return produtos.filter(p => {
            const nomeLower = p.nome.toLowerCase();
            const passaFiltro = filtro.every(termo => nomeLower.includes(termo.toLowerCase()));
            const naoExcluido = !excluir.some(termo => nomeLower.includes(termo.toLowerCase()));
            return passaFiltro && naoExcluido;
        });
    }

    let candidatos = [];

    if (loja === 'amazon') {
        const asins = [...new Set([...html.matchAll(/data-asin="([A-Z0-9]{10})"/g)].map(m => m[1]))];
        const produtos = [];

        for (const asin of asins) {
            const marcador = `data-asin="${asin}"`;
            const idx = html.indexOf(marcador);
            const proximoIdx = html.indexOf('data-asin="', idx + 1);
            const bloco = html.slice(idx, proximoIdx !== -1 ? proximoIdx : idx + 8000);

            const tituloMatch = bloco.match(/<h2[^>]*>\s*<span>([\s\S]*?)<\/span>\s*<\/h2>/i);
            const nome = tituloMatch ? tituloMatch[1].trim() : null;

            const precoMatch = bloco.match(
                /data-cy="price-recipe"[\s\S]*?<span class="a-price"[^>]*>\s*<span class="a-offscreen">R\$(?:&nbsp;)?\s*([\d.,]+)<\/span>/i
            );
            if (!precoMatch) continue;

            const preco = Number(precoMatch[1].replace(/\./g, '').replace(',', '.'));

            const linkMatch = bloco.match(/href="(\/[^"]*\/dp\/[A-Z0-9]{10}[^"]*)"/i);
            let url = linkMatch ? linkMatch[1] : null;
            if (url) url = 'https://www.amazon.com.br' + url.split('/ref=')[0];

            if (nome && preco) produtos.push({ nome, preco, url });
        }

        candidatos = filtraCandidatos(produtos);

    } else if (loja === 'kabum') {
        const match = html.match(/<script id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/i);
        if (match) {
            const dados = JSON.parse(match[1]);
            const itens = dados.props.pageProps.data.catalogServer.data;

            const produtos = itens
                .filter(i => i.available && i.priceWithDiscount)
                .map(i => ({
                    nome: i.name,
                    preco: i.priceWithDiscount,
                    url: `https://www.kabum.com.br/produto/${i.code}/${i.friendlyName}`
                }));

            candidatos = filtraCandidatos(produtos);
        }

    } else if (loja === 'terabyte') {
        const blocos = [...html.matchAll(
            /<div class="tss-card-name">([\s\S]*?)<\/div>[\s\S]*?<div class="tss-card-price">R\$\s*([\d.,]+)<\/div>[\s\S]*?data-tss-link="([^"]+)"/gi
        )];

        const produtos = [];
        const vistos = new Set();

        for (const bloco of blocos) {
            const nome = bloco[1].trim();
            const preco = Number(bloco[2].replace(/\./g, '').replace(',', '.'));
            const url = 'https://www.terabyteshop.com.br' + bloco[3];

            if (vistos.has(url)) continue;
            vistos.add(url);

            if (nome && preco) produtos.push({ nome, preco, url });
        }

        candidatos = filtraCandidatos(produtos);
    }

    if (loja !== 'google_shopping') {
        if (candidatos.length === 0) {
            saida.push({
                json: {
                    nomeMonitorado, loja, precoAlvo,
                    erro: 'Nenhum candidato encontrado',
                    notificar: false
                }
            });
            continue;
        }

        const maisBarato = candidatos.reduce((menor, atual) => atual.preco < menor.preco ? atual : menor);
        const chave = `${nomeMonitorado}__${loja}`;
        const abaixoDoAlvo = maisBarato.preco <= precoAlvo;
        const ultimoPrecoNotificado = staticData.ultimosPrecos[chave];
        const deveNotificar = abaixoDoAlvo && (ultimoPrecoNotificado === undefined || ultimoPrecoNotificado !== maisBarato.preco);

        if (deveNotificar) staticData.ultimosPrecos[chave] = maisBarato.preco;
        if (!abaixoDoAlvo && ultimoPrecoNotificado !== undefined) delete staticData.ultimosPrecos[chave];

        const economia = precoAlvo - maisBarato.preco;

        saida.push({
            json: {
                nomeMonitorado,
                loja,
                item: maisBarato.nome,
                nome: maisBarato.nome,
                preco: maisBarato.preco,
                precoFormatado: maisBarato.preco.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }),
                link: maisBarato.url,
                url: maisBarato.url,
                thumbnail: '',
                economia: economia.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }),
                precoAlvo,
                productId: null,
                notificar: deveNotificar
            }
        });
        continue;
    }

    const resultadosApi = item.json.shopping_results || [];

    const lojasConfiaveis = [
        'kabum', 'amazon', 'pichau', 'terabyte', 'magazine luiza', 'magalu',
        'americanas', 'mercado livre', 'submarino', 'girafa', 'aoc', 'fast shop',
        'casas bahia', 'shoptime', 'novatrend', 'skyhub'
    ];

    const produtosGoogle = resultadosApi
        .filter(r => r.extracted_price)
        .filter(r => r.product_link || r.link)
        .filter(r => {
            const sourceLower = (r.source || '').toLowerCase();
            return lojasConfiaveis.some(l => sourceLower.includes(l));
        })
        .map(r => ({
            nome: r.title,
            preco: r.extracted_price,
            url: r.product_link || r.link,
            thumbnail: r.thumbnail || null,
            loja_real: r.source,
            pageToken: r.immersive_product_page_token || null
        }));

    const candidatosGoogle = filtraCandidatos(produtosGoogle);

    if (candidatosGoogle.length === 0) {
        saida.push({
            json: {
                nomeMonitorado, loja, precoAlvo,
                erro: 'Nenhum candidato encontrado',
                notificar: false
            }
        });
        continue;
    }

    const maisBaratoGoogle = candidatosGoogle.reduce((menor, atual) => atual.preco < menor.preco ? atual : menor);
    const economia = precoAlvo - maisBaratoGoogle.preco;
    const abaixoDoAlvoGoogle = maisBaratoGoogle.preco <= precoAlvo;

    saida.push({
        json: {
            nomeMonitorado,
            loja: maisBaratoGoogle.loja_real,
            item: maisBaratoGoogle.nome,
            nome: maisBaratoGoogle.nome,
            preco: maisBaratoGoogle.preco,
            precoFormatado: maisBaratoGoogle.preco.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }),
            link: maisBaratoGoogle.url,
            url: maisBaratoGoogle.url,
            thumbnail: maisBaratoGoogle.thumbnail || '',
            economia: economia.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }),
            precoAlvo,
            productId: maisBaratoGoogle.pageToken,
            notificar: abaixoDoAlvoGoogle
        }
    });
}

return saida;

const todosOsItens = $input.all();
const staticData = $getWorkflowStaticData('global');
if (!staticData.ultimosPrecosPorLoja) staticData.ultimosPrecosPorLoja = {};

const lojasConfiaveis = [
    'kabum', 'amazon', 'pichau', 'terabyte', 'magazine luiza', 'magalu',
    'americanas', 'mercado livre', 'submarino', 'fast shop',
    'casas bahia', 'shoptime'
];

function precoTotal(loja) {
    return loja.extracted_total || loja.extracted_price || Infinity;
}

function linkValido(url) {
    return typeof url === 'string' && url.trim().length > 0 && url.startsWith('http');
}

function lojaConfiavel(nome) {
    const nomeLower = (nome || '').toLowerCase();
    return lojasConfiaveis.some(l => nomeLower.includes(l));
}

const resultados = [];

todosOsItens.forEach((itemAtual, index) => {
    const dadosProduto = itemAtual.json;
    const original = $('Extrai Melhor Preço').itemMatching(index).json;

    // Se esse item não tinha productId (não era Google Shopping ou não foi elegível), ignora
    if (!original.productId) return;

    const todasAsLojas = dadosProduto.product_results?.stores || [];

    // Filtra: só lojas confiáveis, com preço e link válidos
    const lojasValidas = todasAsLojas.filter(l =>
        lojaConfiavel(l.name) &&
        linkValido(l.link) &&
        precoTotal(l) !== Infinity
    );

    if (lojasValidas.length === 0) return;

    // Ordena do mais barato pro mais caro e pega as 2 primeiras
    const duasMaisBaratas = lojasValidas
        .sort((a, b) => precoTotal(a) - precoTotal(b))
        .slice(0, 2);

    for (const loja of duasMaisBaratas) {
        const preco = precoTotal(loja);

        // Só notifica se estiver de fato abaixo do preço-alvo
        if (preco > original.precoAlvo) continue;

        const nomeLoja = loja.name;
        const chave = `${original.nomeMonitorado}__${nomeLoja}`;

        const ultimoPreco = staticData.ultimosPrecosPorLoja[chave];
        const deveNotificar = ultimoPreco === undefined || ultimoPreco !== preco;

        if (deveNotificar) {
            staticData.ultimosPrecosPorLoja[chave] = preco;

            resultados.push({
                json: {
                    ...original,
                    loja: nomeLoja,
                    preco,
                    precoFormatado: preco.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }),
                    link: loja.link,
                    url: loja.link,
                    economia: (original.precoAlvo - preco).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }),
                    notificar: true
                }
            });
        }
    }
});

return resultados;

